        match build.disable_branch_folding {
            // No flag, --disable_branch_folding, or --disable-branch-folding=true: disable.
            None | Some(None) | Some(Some(true)) => {
                rustflags.push_str(" -Cllvm-args=-simplifycfg-branch-fold-threshold=0");
            }
