        );
        output.push_str(&rust_ident(&self.name));
        output.push_str(
            "| {\n\
                 let _ = input;\n\
             });\n",
        );
        output
    }
}

fn render_field(kind: &FieldKind, seed: usize, field_index: usize) -> String {
    match kind {
