    let totals = value
        .get("data")
        .and_then(|data| data.get(0))
        .and_then(|report| report.get("totals"))
        .context("llvm-cov JSON does not contain data[0].totals")?;

    let metric = |name: &str| -> Result<(u64, u64)> {
        let metric = totals
            .get(name)
            .with_context(|| format!("coverage summary lacks `{name}`"))?;
        let count = metric
            .get("count")
            .and_then(toml::Value::as_integer)
            .and_then(|value| u64::try_from(value).ok())
            .unwrap_or_default();
        let covered = metric
            .get("covered")
            .and_then(toml::Value::as_integer)
            .and_then(|value| u64::try_from(value).ok())
            .unwrap_or_default();
        Ok((count, covered))
    };

    let (lines_total, lines_covered) = metric("lines")?;
    let (regions_total, regions_covered) = metric("regions")?;
    Ok(CoverageRow {
        crate_name: crate_name.into(),
        strategy: strategy.into(),
        lines_total,
        lines_covered,
        regions_total,
        regions_covered,
    })
}

pub fn parse_llvm_cov_summary_file(
    crate_name: impl Into<String>,
    strategy: impl Into<String>,
    path: &Path,
) -> Result<CoverageRow> {
    let json = std::fs::read_to_string(path)
        .with_context(|| format!("failed to read coverage summary {}", path.display()))?;
    parse_llvm_cov_summary(crate_name, strategy, &json)
}

pub fn markdown_table(rows: &[CoverageRow]) -> String {
    let mut output = String::new();
    output.push_str("| Crate | Strategy | Lines covered | Line coverage | Regions covered | Region coverage |\n");
    output.push_str("|---|---:|---:|---:|---:|---:|\n");
    for row in rows {
        output.push_str(&format!(
            "| {} | {} | {}/{} | {:.1}% | {}/{} | {:.1}% |\n",
            row.crate_name,
            row.strategy,
            row.lines_covered,
            row.lines_total,
            row.line_percent(),
            row.regions_covered,
            row.regions_total,
            row.region_percent(),
        ));
    }
    output
}

pub fn csv(rows: &[CoverageRow]) -> String {
    let mut output =
        String::from("crate,strategy,lines_covered,lines_total,line_percent,regions_covered,regions_total,region_percent\n");
    for row in rows {
        output.push_str(&format!(
            "{},{},{},{},{:.2},{},{},{:.2}\n",
            row.crate_name,
            row.strategy,
            row.lines_covered,
            row.lines_total,
            row.line_percent(),
            row.regions_covered,
            row.regions_total,
            row.region_percent(),
        ));
    }
    output
}

pub fn ensure_three_crates(rows: &[CoverageRow]) -> Result<()> {
    let mut crates: Vec<&str> = rows.iter().map(|row| row.crate_name.as_str()).collect();
    crates.sort_unstable();
    crates.dedup();
    if crates.len() < 3 {
        bail!(
            "coverage comparison requires at least 3 crates, found {}",
            crates.len()
        );
    }
    Ok(())
}

fn percent(covered: u64, total: u64) -> f64 {
    if total == 0 {
        0.0
    } else {
        covered as f64 * 100.0 / total as f64
    }
}

/// Convert the small JSON subset used by llvm-cov summaries into TOML.
///
/// `cargo-fuzz` already depends on a full TOML parser but not directly on
/// serde_json. LLVM's summary shape is regular JSON, so this conversion is
/// isolated here and can be replaced by serde_json if the CLI grows.
fn serde_json_to_toml(json: &str) -> Result<toml::Value> {
    let json_value: serde_json::Value = serde_json::from_str(json)?;
    let toml_text = toml::to_string(&json_to_toml_value(&json_value))?;
    toml::from_str(&toml_text).context("failed to interpret converted coverage summary")
}

fn json_to_toml_value(value: &serde_json::Value) -> toml::Value {
    match value {
        serde_json::Value::Null => toml::Value::String(String::new()),
        serde_json::Value::Bool(value) => toml::Value::Boolean(*value),
        serde_json::Value::Number(number) => {
            if let Some(value) = number.as_i64() {
                toml::Value::Integer(value)
            } else if let Some(value) = number.as_f64() {
                toml::Value::Float(value)
            } else {
                toml::Value::String(number.to_string())
            }
        }
        serde_json::Value::String(value) => toml::Value::String(value.clone()),
        serde_json::Value::Array(values) => {
            toml::Value::Array(values.iter().map(json_to_toml_value).collect())
        }
        serde_json::Value::Object(map) => {
            let mut table = toml::map::Map::new();
            for (key, value) in map {
                table.insert(key.clone(), json_to_toml_value(value));
            }
            toml::Value::Table(table)
        }
    }
}

