        }

        if self.expect_three_crates {
            ensure_three_crates(&rows)?;
        }

        match self.format {
            ReportFormat::Markdown => print!("{}", markdown_table(&rows)),
            ReportFormat::Csv => print!("{}", csv(&rows)),
        }
        Ok(())
    }
}

